fn v3_epicops_buff_window(self:&mut TeamPlan, version, rnd, player, data, goal_data, plan) -> bool

// ── 1단계: 수리(Repair) 우선 (epic.rs:635)
let team = player.info.team;                 // PlayerState+0x930
let cache = data.cache;                      // OperationData+0x0
match v3_epicops_repair_need(team, cache, plan) {   // -> u8, range 0..3
  1 => { self.objective = Some(MainObjective::Repair);   // +0x41f = 7   (L637)
         self.chats.push(Chat::Repair(0));               //              (L638)
         return true; }                                  //              (L639)
  2 => { self.objective = Some(MainObjective::Repair);   // +0x41f = 7   (L642)
         return true; }        // 콜 없이 목표만          //              (L643)
  _ => {}                      // 0 = 수리 불필요 → 2단계
}

// ── 2단계: 세르펜 뺏김 대응 (epic.rs:651~658)
if is_object_being_taken_by_enemy(player, data, goal_data, self, WavePriorityObject::Serpen)
   && v3_serpen_contest_clear_win(version, player, data, self) {
     self.eo_serpen_punish_issues += 1;                        // +0x410      (L653)
     self.objective = Some(MainObjective::Serpen{ phase: ObjectPhase::Setup, with_battle: true });
                                                               // +0x41f/0x420/0x421 = 1/1/1 (L654)
     self.chats.push(Chat::SerpenSetup(0));                     //             (L658)
     return true;
}
// 위 두 조건 중 하나라도 거짓이면 3단계로 (두 검사는 단락평가 — clear_win 은 taken 이 참일 때만 호출)

// ── 3단계: 라인 압박(press) 콜 창 (epic.rs:664~682)
let strategy = player.strategy(rnd, cache.game);          // Strategy 24B, sret      (L664)
let Some(group_line) = v3_epic_group_line(strategy.morgard_use, player, data)
    else { return false };            // 반환이 -1(None) 이면 즉시 false          (L665)

if self.v3_press_chat_line == Some(group_line) { return false; }  // 라인이 안 바뀌었으면 무음 (L666)

// 아군 5슬롯을 0..5 순서로 훑어 '압박 콜을 낼 자격이 있는 첫 슬롯'을 찾는다 (L667~670)
//  (Iterator::find 가 5회 완전 언롤됨 — 별도 클로저 define 없음, fnparts 로 확인)
let announcer: Option<usize> = (0..5).find(|&x| {
    cache.player_champion[team][x].is_some()            // null 이면 스킵          (L668)
    && v3_epic_formation_role(strategy.morgard_use, Position::from_index(x), player, data)
         .is_some_and(|f| !f.is_split)                  // 스플릿 역할은 콜 안 함  (L669~670)
});
// IR 술어 실체: r = role 의 첫 바이트(is_split 바이트, 2=None)
//   found = (r != 2) XOR (r & 1)  →  r==0 만 true (Some & is_split==false)

if announcer == Some(player.info.position.as_index()) {         //                (L672)
    // 내가 그 대표자다 → 콜 발화
    self.chats.push(if self.v3_press_chat_line.is_none() { Chat::Press(group_line, 0) }
                    else                                 { Chat::PressChange(group_line, 0) });
}                                                                //               (L673)
self.v3_press_chat_line = Some(group_line);   // 콜을 냈든 안 냈든 항상 갱신      (L679)
return false;                                  // 압박 경로는 언제나 false        (L682)

// ※ team >= 2 이면 player_champion 인덱싱에서 panic_bounds_check(team, 2) → 패닉
